import { z } from 'zod';
import { CosmosProfileSchema } from './cosmos-profile';
import { CosmosProfileUrlSchema } from './cosmos';

export const AuthenticatedReferenceProviderSchema = z.enum([
  'pinterest',
  'arena',
  'x',
]);
export const ReferenceProviderSchema = z.enum([
  'cosmos',
  'pinterest',
  'arena',
  'x',
]);
export type ReferenceProvider = z.infer<typeof ReferenceProviderSchema>;
export type AuthenticatedReferenceProvider = z.infer<
  typeof AuthenticatedReferenceProviderSchema
>;
export const ReferenceIdSchema = z
  .string()
  .min(1)
  .max(200)
  .regex(/^[a-zA-Z0-9:_-]+$/);
const profileHosts: Record<string, ReferenceProvider> = {
  'www.cosmos.so': 'cosmos',
  'www.pinterest.com': 'pinterest',
  'www.are.na': 'arena',
  'x.com': 'x',
};
const authenticatedProfileUrl = z
  .string()
  .url()
  .refine((value) => {
    const url = new URL(value);
    return (
      url.protocol === 'https:' &&
      !url.username &&
      !url.password &&
      !url.port &&
      !url.search &&
      !url.hash &&
      AuthenticatedReferenceProviderSchema.safeParse(profileHosts[url.hostname])
        .success &&
      /^\/[a-zA-Z0-9_-]+\/?$/.test(url.pathname)
    );
  }, 'Use a canonical reference provider profile URL');
export const ReferenceProfileSchema = z
  .object({
    id: ReferenceIdSchema,
    username: z.string().min(1).max(100),
    title: z.string().max(500),
    url: z.union([CosmosProfileUrlSchema, authenticatedProfileUrl]),
  })
  .transform((profile) =>
    profileHosts[new URL(profile.url).hostname] === 'cosmos'
      ? CosmosProfileSchema.parse(profile)
      : profile,
  );
export type ReferenceProfile = z.infer<typeof ReferenceProfileSchema>;
export const referenceProvider = (
  profile: ReferenceProfile,
): ReferenceProvider =>
  ReferenceProviderSchema.parse(profileHosts[new URL(profile.url).hostname]);
export const ReferenceCollectionSchema = z.object({
  id: ReferenceIdSchema,
  title: z.string().min(1).max(500),
  description: z.string().max(10_000).nullable(),
  url: z.string().url().nullable(),
  total: z.number().int().nonnegative().nullable(),
  parentId: ReferenceIdSchema.nullable(),
  children: z.array(ReferenceIdSchema).max(10_000),
});
export type ReferenceCollection = z.infer<typeof ReferenceCollectionSchema>;
export const ReferenceDiscoveryRequestSchema = z.union([
  z.object({ url: CosmosProfileUrlSchema }).strict(),
  z.object({ provider: AuthenticatedReferenceProviderSchema }).strict(),
]);
export type ReferenceDiscoveryRequest = z.infer<
  typeof ReferenceDiscoveryRequestSchema
>;
export const referenceSourceId = ({
  profile,
  collection,
}: {
  profile: ReferenceProfile;
  collection: Pick<ReferenceCollection, 'id' | 'url'>;
}) => {
  if (referenceProvider(profile) === 'cosmos') {
    if (!collection.url) throw new Error('Cosmos collections require a URL');
    return collection.url;
  }
  return `account:${profile.id}:collection:${collection.id}`;
};

export const ReferenceCatalogSchema = z.object({
  collections: z.array(ReferenceCollectionSchema),
  total: z.number().int().nonnegative().nullable(),
  nextCursor: z.string().min(1).max(4096).nullable(),
});
export const ReferenceCatalogPageSchema = ReferenceCatalogSchema.extend({
  profile: ReferenceProfileSchema,
});
export type ReferenceCatalogPage = z.infer<typeof ReferenceCatalogPageSchema>;

export const referenceScopeDisclosure: Record<ReferenceProvider, string> = {
  cosmos:
    'Public collections, including nested public collections. The profile URL identifies public content, not verified ownership.',
  pinterest:
    'Selected boards available to the connected account, including accessible private and collaborative boards.',
  arena:
    'Channels created by the connected user. Nested channels are listed as unsupported references; select those channels separately to import their contents.',
  x: 'Bookmarks available through the X API as one collection. Provider access limits can exclude saved posts. Text, images, and available video covers are imported; videos and bookmark folders are not imported.',
};
